function n(i){const t=new Set;for(const e of i){if(!e.id.trim()||t.has(e.id))throw new Error("ChangeReview requires unique non-empty ids.");if(e.state&&!["pending","applying","applied","failed"].includes(e.state))throw new Error("Unknown review state.");t.add(e.id)}return{items:i,actionable:i.filter(e=>e.state!=="applied").map(e=>e.id),applying:i.some(e=>e.state==="applying")}}export{n as reviewChanges};
